  .dgs-bc-orb-blue {
    width: 460px;
    height: 460px;
    background: #2297ff;
    top: 160px;
    right: -170px;
  }

  .dgs-bc-orb-pink {
    width: 460px;
    height: 460px;
    background: #c75cff;
    bottom: 320px;
    left: 38%;
  }

  .dgs-bc-scan-light {
    position: absolute;
    width: 640px;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.65), transparent);
