  }

  .dgs-bc-scan-one {
    top: 22%;
    left: -10%;
  }

  .dgs-bc-scan-two {
    bottom: 18%;
    right: -8%;
  }

  .dgs-bc-container {
    width: 100%;
    max-width: 1480px;
    margin: 0 auto;
    position: relative;
    z-index: 10;
  }

